import React, { useEffect, useRef, useState, useContext } from "react";
import { AuthContext } from "../Context/AuthContext";
import { eraseLine } from "../utils/erase";

function CanvasBoard({ socket }) {
  const canvasRef = useRef(null);
  const ctxRef = useRef(null);
  const { user } = useContext(AuthContext);

  const [drawing, setDrawing] = useState(false);
  const [lastPos, setLastPos] = useState(null);
  const [currentTool, setCurrentTool] = useState("pen");

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    canvas.width = window.innerWidth - 300; // Account for user list sidebar
    canvas.height = window.innerHeight - 200; // Account for header and toolbar

    const ctx = canvas.getContext("2d");
    ctx.fillStyle = "white";
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.strokeStyle = "black";
    ctx.lineWidth = 2;
    ctxRef.current = ctx;

    // Handle window resize
    const handleResize = () => {
      canvas.width = window.innerWidth - 300;
      canvas.height = window.innerHeight - 200;
      ctx.fillStyle = "white";
      ctx.fillRect(0, 0, canvas.width, canvas.height);
    };

    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  const startDrawing = (e) => {
    if (user.role === "viewer") return;
    setDrawing(true);
    const { offsetX, offsetY } = e.nativeEvent;
    setLastPos({ x: offsetX, y: offsetY });
    ctxRef.current.beginPath();
    ctxRef.current.moveTo(offsetX, offsetY);
  };

  const draw = (e) => {
    if (!drawing || user.role === "viewer") return;
    const { offsetX, offsetY } = e.nativeEvent;
    const ctx = ctxRef.current;
    if (!lastPos) return;

    // Draw locally first for instant feedback
    if (currentTool === "eraser") {
      eraseLine(ctx, lastPos.x, lastPos.y, offsetX, offsetY);
    } else {
      ctx.globalCompositeOperation = "source-over";
      ctx.strokeStyle = "black";
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(lastPos.x, lastPos.y);
      ctx.lineTo(offsetX, offsetY);
      ctx.stroke();
      ctx.closePath();
    }

    // Emit drawing info to server
    socket.emit("draw", {
      x0: lastPos.x,
      y0: lastPos.y,
      x1: offsetX,
      y1: offsetY,
      tool: currentTool,
    });

    setLastPos({ x: offsetX, y: offsetY });
  };

  const stopDrawing = () => {
    setDrawing(false);
    setLastPos(null);
    if (ctxRef.current) {
      ctxRef.current.closePath();
    }
  };

  useEffect(() => {
    const receiveDraw = (data) => {
      const ctx = ctxRef.current;
      if (!ctx) return;

      if (data.tool === "eraser") {
        eraseLine(ctx, data.x0, data.y0, data.x1, data.y1);
      } else {
        ctx.globalCompositeOperation = "source-over";
        ctx.strokeStyle = "black";
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(data.x0, data.y0);
        ctx.lineTo(data.x1, data.y1);
        ctx.stroke();
        ctx.closePath();
      }
    };

    // Listen for clear board events from server
    const handleClearBoard = () => {
      const canvas = canvasRef.current;
      if (canvas) {
        const ctx = canvas.getContext("2d");
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = "white";
        ctx.fillRect(0, 0, canvas.width, canvas.height);
      }
    };

    socket.on("draw", receiveDraw);
    socket.on("clearBoard", handleClearBoard);

    return () => {
      socket.off("draw", receiveDraw);
      socket.off("clearBoard", handleClearBoard);
    };
  }, [socket]);

  const handleClearBoard = () => {
    if (user.role !== "admin") return;

    // Emit clear board event to server so all users get cleared
    socket.emit("clearBoard");

    // Also clear locally for immediate feedback
    const canvas = canvasRef.current;
    if (canvas) {
      const ctx = canvas.getContext("2d");
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = "white";
      ctx.fillRect(0, 0, canvas.width, canvas.height);
    }
  };

  return (
    <div className="flex flex-col h-full">
      {/* Beautiful Tool Bar */}
      <div className="flex justify-center p-6 bg-gradient-to-r from-blue-50 via-indigo-50 to-purple-50 border-b border-blue-200 shadow-sm">
        <div className="flex items-center space-x-4 bg-white/80 backdrop-blur-lg rounded-3xl p-3 shadow-xl border border-white/50">
          {/* Pen Tool */}
          <button
            onClick={() => setCurrentTool("pen")}
            className={`group relative px-8 py-4 rounded-2xl font-semibold transition-all duration-300 transform hover:scale-110 ${
              currentTool === "pen" 
                ? "bg-gradient-to-r from-blue-500 to-purple-600 text-white shadow-2xl" 
                : "bg-white/90 text-gray-700 hover:bg-blue-50 border-2 border-gray-200 hover:border-blue-300"
            }`}
          >
            <div className="flex items-center space-x-3">
              <div className={`w-8 h-8 rounded-full flex items-center justify-center ${
                currentTool === "pen" ? "bg-white/20" : "bg-blue-100"
              }`}>
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" />
                </svg>
              </div>
              <span className="font-medium">Pen</span>
            </div>
            {currentTool === "pen" && (
              <div className="absolute -bottom-1 left-1/2 transform -translate-x-1/2 w-2 h-2 bg-blue-500 rounded-full"></div>
            )}
          </button>

          {/* Eraser Tool */}
          <button
            onClick={() => setCurrentTool("eraser")}
            className={`group relative px-8 py-4 rounded-2xl font-semibold transition-all duration-300 transform hover:scale-110 ${
              currentTool === "eraser" 
                ? "bg-gradient-to-r from-blue-500 to-purple-600 text-white shadow-2xl" 
                : "bg-white/90 text-gray-700 hover:bg-blue-50 border-2 border-gray-200 hover:border-blue-300"
            }`}
          >
            <div className="flex items-center space-x-3">
              <div className={`w-8 h-8 rounded-full flex items-center justify-center ${
                currentTool === "eraser" ? "bg-white/20" : "bg-blue-100"
              }`}>
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                </svg>
              </div>
              <span className="font-medium">Eraser</span>
            </div>
            {currentTool === "eraser" && (
              <div className="absolute -bottom-1 left-1/2 transform -translate-x-1/2 w-2 h-2 bg-blue-500 rounded-full"></div>
            )}
          </button>

          {/* Clear Board Button (Admin Only) */}
          {user.role === "admin" && (
            <button
              onClick={handleClearBoard}
              className="group relative px-8 py-4 bg-gradient-to-r from-red-500 to-pink-600 text-white rounded-2xl font-semibold hover:from-red-600 hover:to-pink-700 transition-all duration-300 transform hover:scale-110 shadow-xl hover:shadow-2xl"
            >
              <div className="flex items-center space-x-3">
                <div className="w-8 h-8 rounded-full bg-white/20 flex items-center justify-center">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                  </svg>
                </div>
                <span className="font-medium">Clear Board</span>
              </div>
              <div className="absolute -bottom-1 left-1/2 transform -translate-x-1/2 w-2 h-2 bg-red-500 rounded-full"></div>
            </button>
          )}
        </div>
      </div>

      {/* Canvas Container with Beautiful Background */}
      <div className="flex-1 flex justify-center items-center bg-gradient-to-br from-gray-50 via-blue-50 to-indigo-50 p-6 relative overflow-hidden">
        {/* Decorative Background Elements */}
        <div className="absolute inset-0 opacity-5">
          <div className="absolute top-20 left-20 w-32 h-32 bg-blue-400 rounded-full blur-3xl"></div>
          <div className="absolute bottom-20 right-20 w-40 h-40 bg-purple-400 rounded-full blur-3xl"></div>
          <div className="absolute top-1/2 left-1/2 w-24 h-24 bg-indigo-400 rounded-full blur-3xl transform -translate-x-1/2 -translate-y-1/2"></div>
        </div>

        <div className="relative z-10">
          {/* Canvas with Enhanced Styling */}
          <div className="relative">
            <canvas
              ref={canvasRef}
              className="border-4 border-white shadow-2xl rounded-2xl bg-white"
              onMouseDown={startDrawing}
              onMouseMove={draw}
              onMouseUp={stopDrawing}
              onMouseLeave={stopDrawing}
              style={{
                backgroundColor: "white",
                cursor: currentTool === "eraser" ? "crosshair" : "pointer",
              }}
            />

            {/* Canvas Info Overlay */}
            <div className="absolute top-6 left-6 bg-white/95 backdrop-blur-lg rounded-2xl px-4 py-3 shadow-xl border border-white/50">
              <div className="text-sm text-gray-700">
                <div className="font-semibold flex items-center space-x-2">
                  <span>Current Tool:</span>
                  <span className={`px-3 py-1 rounded-full text-xs font-medium ${
                    currentTool === "pen" 
                      ? "bg-blue-100 text-blue-700" 
                      : "bg-gray-100 text-gray-700"
                  }`}>
                    {currentTool === "pen" ? "✏️ Pen" : "🧽 Eraser"}
                  </span>
                </div>
                <div className="text-xs text-gray-500 mt-1">Click and drag to draw</div>
              </div>
            </div>

            {/* Status Indicator */}
            <div className="absolute top-6 right-6 bg-green-500/90 backdrop-blur-lg rounded-full px-3 py-2 shadow-lg">
              <div className="flex items-center space-x-2">
                <div className="w-2 h-2 bg-white rounded-full animate-pulse"></div>
                <span className="text-white text-xs font-medium">Live</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default CanvasBoard;
